using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using LWS.TruckSports.Editor;
namespace LWS.TruckBogSnorkelling.Editor {
 public static class BogHardCourseAuthoring {
  public static void Upgrade(){var scene=EditorSceneManager.OpenScene(BogAuthoring.Scene);Install(UnityEngine.Object.FindAnyObjectByType<BogMatch>());EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
  public static void Install(BogMatch match){var course=match.course;if(course.hardTerrain!=null)return;course.normalTerrain=course.terrain;course.normalScenery=GameObject.Find("Bog banks and authentic installed course props");course.normalCheckpoints=(float[])course.checkpoints.Clone();course.normalLogs=(float[])course.logs.Clone();course.normalWaterPosition=course.water.position;course.normalWaterScale=course.water.localScale;foreach(var label in UnityEngine.Object.FindObjectsByType<TextMesh>(FindObjectsInactive.Include))if(label.name.StartsWith("Physical dive marker")||label.name.StartsWith("Bog checkpoint")||label.name=="Longer shallow branch")label.transform.SetParent(course.normalScenery.transform,true);
   string folder="Assets/TruckBogSnorkelling/HardCourse";Directory.CreateDirectory(folder);var data=new TerrainData{name="Six flooded galleries · native Hard course",heightmapResolution=513,alphamapResolution=128,size=new Vector3(320,30,710)};data.terrainLayers=course.normalTerrain.terrainData.terrainLayers;var heights=new float[513,513];for(int z=0;z<513;z++)for(int x=0;x<513;x++){float wx=-160+x/512f*320,wz=-20+z/512f*710;heights[z,x]=(BogCourse.HardFloor(wx,wz)+5)/30;}data.SetHeights(0,0,heights);var paints=new float[128,128,data.terrainLayers.Length];for(int z=0;z<128;z++)for(int x=0;x<128;x++){float wx=-160+x/127f*320,wz=-20+z/127f*710;float mud=.95f*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(22,36,Mathf.Abs(wx-BogCourse.Center(wz)))));paints[z,x,0]=1-mud;if(data.terrainLayers.Length>1)paints[z,x,1]=mud;}data.SetAlphamaps(0,0,paints);AssetDatabase.CreateAsset(data,folder+"/Flooded galleries terrain.asset");course.hardTerrain=Terrain.CreateTerrainGameObject(data).GetComponent<Terrain>();course.hardTerrain.name="Hard course · real long submerged trench";course.hardTerrain.transform.position=new Vector3(-160,-5,-20);course.hardTerrain.materialTemplate=course.normalTerrain.materialTemplate;course.hardTerrain.drawInstanced=true;course.hardTerrain.heightmapPixelError=5;
   var root=new GameObject("Hard · flooded stone galleries and breathing pockets");course.hardScenery=root;var rock=SportsEventAuthoring.Contact("TruckBogSnorkelling","Flooded gallery stone contact",.35f,.02f);
   int index=0;foreach(var span in BogCourse.HardSpans){float length=span.y-span.x;var roof=new GameObject("Submerged gallery "+(++index)+" · genuine no-air roof").transform;roof.SetParent(root.transform,false);roof.position=new Vector3(BogCourse.Center((span.x+span.y)/2),1.1f,(span.x+span.y)/2);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(roof,"Assets/PinwheelStudio/Vista/Personal/Samples/Prefabs/VistaSample_DesertRock.prefab",new Vector3(51,7,length),0,true,"TruckBogSnorkelling");var collider=roof.gameObject.AddComponent<BoxCollider>();collider.center=new Vector3(0,3.5f,0);collider.size=new Vector3(51,7,length);collider.sharedMaterial=rock;
    foreach(float z in new[]{span.x-9,span.y+12}){var point=new Vector3(BogCourse.Center(z),4,z);var marker=SportsEventAuthoring.Label("Gallery airway marker",z<span.x?"SUBMERGED GALLERY "+index+" · KEEP MOVING":"OPEN SKY · BREATHE",point,.18f,z<span.x?new Color(1,.65f,.13f):new Color(.54f,1,.74f));marker.transform.SetParent(root.transform,true);marker.gameObject.AddComponent<LWS.TruckSports.SportsPerCameraBillboard>();}
   }
   for(int i=0;i<210;i++){float z=-5+i*3.25f;int side=i%2==0?-1:1;var p=new Vector3(BogCourse.Center(z)+side*(29+i%4*1.3f),0,z);p.y=BogCourse.HardFloor(p.x,p.z);SportsRallyAuthoring.Prop(root.transform,"Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Grass_01.prefab",p,new Vector3(3,2.6f,3));if(i%6==0){var tree=new GameObject("Gallery bank owned tree "+i).transform;tree.SetParent(root.transform,false);tree.position=p+Vector3.right*side*12;tree.position=new Vector3(tree.position.x,BogCourse.HardFloor(tree.position.x,z),z);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(tree,"Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Tree_07.prefab",new Vector3(7,11,7),0,false,"TruckBogSnorkelling");}}
   foreach(float z in new[]{22f,70,121,170,221,270,321,370,421,470,521,570,621,650})for(int side=-1;side<=1;side+=2){var point=new Vector3(BogCourse.Center(z)+side*24,BogCourse.HardFloor(BogCourse.Center(z)+side*24,z),z);SportsRallyAuthoring.Prop(root.transform,"Assets/RoadPropsPack/URP/Prefabs/TrafficCone_URP.prefab",point,new Vector3(1.8f,2.5f,1.8f));}
   course.SelectCourse(false);EditorUtility.SetDirty(course);EditorUtility.SetDirty(match);AssetDatabase.SaveAssets();File.WriteAllText("Logs/TruckSports/EssentialRelease/bog-hard-authoring.txt","PASS saved native additional650m Hard course; classic untouched. Runtime oxygen/driving tests still required.");
  }
 }
}
